import { Directive, ElementRef, inject } from '@angular/core';

@Directive({
  selector: '[appMascaraNumeros]',
  standalone: true,
  host: {
    '(input)': 'onInput()',
  },
})
export class MascaraNumerosDirective {
  private readonly el = inject<ElementRef<HTMLInputElement>>(ElementRef).nativeElement;
  private syncing = false;

  onInput(): void {
    if (this.syncing) return;

    const rawValue = this.el.value;
    
    const start = this.el.selectionStart || 0;
    const beforeCursor = rawValue.substring(0, start);
    const digitsBeforeCursor = beforeCursor.replace(/\D/g, '').length;

    const clean = rawValue.replace(/\D/g, '');
    const formatted = clean ? parseInt(clean, 10).toLocaleString('en-US') : '';

    if (formatted === rawValue) return;

    this.el.value = formatted;

    let newCursorPos = 0;
    let digitsSeen = 0;
    for (let i = 0; i < formatted.length; i++) {
       if (/\d/.test(formatted[i])) {
          digitsSeen++;
       }
       if (digitsSeen === digitsBeforeCursor) {
          newCursorPos = i + 1;
          break;
       }
    }
    
    this.el.setSelectionRange(newCursorPos, newCursorPos);

    this.syncing = true;
    this.el.dispatchEvent(new Event('input', { bubbles: true }));
    this.syncing = false;
  }
}
